#include <Cellerator/compiler/reflection/implement_inline_planning_ir_blocks_v1.hh>
#include <algorithm>
#include <set>
namespace cellerator::compiler::reflection::v1 {
inline_planning_status_v1 validate_inline_planning_block_v1(const inline_planning_block_v1&b)noexcept{if(b.planning_point.empty())return inline_planning_status_v1::missing_point;std::set<std::string> forced;for(const auto&e:b.edits){if(e.subject.empty())return inline_planning_status_v1::invalid_subject;if(e.kind==planning_edit_kind_v1::change_cost&&e.cost.empty())return inline_planning_status_v1::invalid_cost;if(e.kind==planning_edit_kind_v1::force_candidate&&!e.unsafe_acknowledged)return inline_planning_status_v1::force_not_acknowledged;if(e.kind==planning_edit_kind_v1::force_candidate&&!forced.insert(e.subject).second)return inline_planning_status_v1::conflicting_edit;}return inline_planning_status_v1::valid;}
reflected_search_space_v1 apply_inline_planning_block_v1(const reflected_search_space_v1&s,const inline_planning_block_v1&b){auto r=s;if(validate_inline_planning_block_v1(b)!=inline_planning_status_v1::valid)return r;for(const auto&e:b.edits){auto it=std::find_if(r.alternatives.begin(),r.alternatives.end(),[&](const auto&a){return a.candidate==e.subject;});if(e.kind==planning_edit_kind_v1::offer_candidate&&it==r.alternatives.end())r.alternatives.push_back({{}, {}, {}, {}, e.cost,e.subject,"",reflected_selection_v1::offered});else if(e.kind==planning_edit_kind_v1::remove&&it!=r.alternatives.end())r.alternatives.erase(it);else if(e.kind==planning_edit_kind_v1::change_cost&&it!=r.alternatives.end())it->cost_ns=e.cost;else if(e.kind==planning_edit_kind_v1::force_candidate&&it!=r.alternatives.end())it->selection=reflected_selection_v1::forced;}return r;}
}
